#!/usr/bin/env bash
# Host KAT runner: the core derives exactly the addresses in the shared derivation vectors
# (vectors/derivation/*.txt in the core, generated by an independent implementation,
# vectors/derivation/generate.py), for both the 12- and the 24-word BIP39 mnemonic.
#
#   RED    -DDERIVATION_VECTORS_RED makes plausible porting mistakes in the KAT itself (wrong
#          master key per tree, Taproot over m/84', legacy chains swapped, the single-tree
#          wallet). Every RED case MUST fail, which proves the comparison is not vacuous; every
#          GUARD case must pass.
#   GREEN  the core as shipped: every case passes, ALL PASS, exit 0. Both arms under ASan.
#   GUARD SELF-TEST  the 24-word guard (DERIV-24) is shown to bite: the shipped arm run on a copy
#          of abandon-art.txt whose phrase has a bad checksum must fail mnemonic_bip39_valid, and
#          the word-count pairing must reject a 12-word file held to 24 words.
#
# CORE_DIR may be set to run against a core checkout other than the android submodule.
# Exit code 0 = gate held, 1 = it did not.
set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../../../.." && pwd)"
CORE_DIR="${CORE_DIR:-$REPO_ROOT/native/src/main/jni/digibytewallet-core}"
# 12-word (abandon x11 about) and 24-word (abandon x23 art, DERIV-24) BIP39 test vectors, each
# with no passphrase, "TREZOR", and (24-word) a passphrase with spaces, case, digits and punctuation.
# Each file is paired with the word count its phrase must have (the KAT prints WORDS n), so a
# file regenerated from the wrong phrase cannot pass under a 24-word name.
VECTOR_FILES=("$CORE_DIR/vectors/derivation/abandon-about.txt"
              "$CORE_DIR/vectors/derivation/abandon-about-trezor.txt"
              "$CORE_DIR/vectors/derivation/abandon-art.txt"
              "$CORE_DIR/vectors/derivation/abandon-art-trezor.txt"
              "$CORE_DIR/vectors/derivation/abandon-art-correct-horse.txt")
VECTOR_WORDS=(12 12 24 24 24)
BUILD_DIR="$(mktemp -d)"
trap 'rm -rf "$BUILD_DIR"' EXIT

CC="${CC:-clang}"
export ASAN_OPTIONS="halt_on_error=1 abort_on_error=1 symbolize=0"
SAN_RE='ERROR: AddressSanitizer|ERROR: LeakSanitizer|runtime error:'

RED_CASES=(bip84_from_master_pubkey bip84_from_signing_key bip86_from_master_pubkey
           bip86_from_signing_key legacy_p2pkh_from_master_pubkey legacy_p2pkh_from_signing_key
           legacy_p2wpkh_from_master_pubkey legacy_p2wpkh_from_signing_key
           recipe_wallet_watches_every_vector)
GUARD_CASES=(vectors_parsed mnemonic_bip39_valid bip39_seed)

shopt -s nullglob
SHA3_SRCS=("$CORE_DIR"/crypto/sha3/*.c)
shopt -u nullglob

UNITS=(
    "$CORE_DIR/BRWallet.c"
    "$CORE_DIR/BRWalletFilterElements.c"
    "$CORE_DIR/BRTransaction.c"
    "$CORE_DIR/BRDigiDollar.c"
    "$CORE_DIR/BRKey.c"
    "$CORE_DIR/BRNetwork.c"
    "$CORE_DIR/BRBIP32Sequence.c"
    "$CORE_DIR/BRBIP39Mnemonic.c"
    "$CORE_DIR/BRAddress.c"
    "$CORE_DIR/BRSet.c"
    "$CORE_DIR/BRDigiAsset.c"
    "$CORE_DIR/BRCrypto.c"
    "$CORE_DIR/BRBase58.c"
    "$CORE_DIR/BRBech32.c"
    "$CORE_DIR/crypto/groestl.c"
    "$CORE_DIR/crypto/skein.c"
    "$CORE_DIR/crypto/qubit.c"
    "$CORE_DIR/crypto/odocrypt.c"
    "${SHA3_SRCS[@]}"
)

build() {
    local out="$1"; shift
    "$CC" -w -include stdint.h -g -fsanitize=address -fno-omit-frame-pointer "$@" \
        -I "$CORE_DIR" \
        -I "$CORE_DIR/secp256k1/include" \
        "$SCRIPT_DIR/derivation_vectors_kat_main.c" \
        "${UNITS[@]}" \
        -lpthread -lm \
        -o "$out"
}

for VECTORS in "${VECTOR_FILES[@]}"; do
    [ -s "$VECTORS" ] || { echo "GATE FAILURE: no vector file at $VECTORS."; exit 1; }
done

FAIL=0
build "$BUILD_DIR/red" -DDERIVATION_VECTORS_RED || { echo "GATE FAILURE: comparison arm did not compile."; exit 1; }
build "$BUILD_DIR/green" || { echo "GATE FAILURE: shipped arm did not compile."; exit 1; }

# words_match <kat output> <expected word count>: the KAT counted exactly that many words.
words_match() { <<<"$1" grep -qx "WORDS $2"; }

for vi in "${!VECTOR_FILES[@]}"; do
VECTORS="${VECTOR_FILES[$vi]}"; WANT_WORDS="${VECTOR_WORDS[$vi]}"
echo "=== $(basename "$VECTORS") ($WANT_WORDS words)"
echo "--- COMPARISON ARM (-DDERIVATION_VECTORS_RED): every RED case MUST fail, every GUARD case pass ---"
out="$("$BUILD_DIR/red" "$VECTORS" 2>&1)"; rc=$?
<<<"$out" grep -Eq "$SAN_RE" && { echo "  [red] GATE FAILURE: sanitizer report"; FAIL=1; }
[ $rc -eq 0 ] && { echo "  [red] GATE FAILURE: the comparison arm exited 0; it proves nothing"; FAIL=1; }
for c in "${RED_CASES[@]}"; do
    if <<<"$out" grep -q "^RESULT $c fail$"; then echo "  [red $c] failed, as it must"
    else echo "  [red $c] GATE FAILURE: did not fail in the comparison arm"; FAIL=1; fi
done
for c in "${GUARD_CASES[@]}"; do
    if <<<"$out" grep -q "^RESULT $c pass$"; then echo "  [red $c] GUARD held"
    else echo "  [red $c] GATE FAILURE: GUARD case did not hold"; <<<"$out" grep "^FAIL: $c" | sed 's/^/      /'; FAIL=1; fi
done

echo "--- SHIPPED ARM: every case MUST pass, ALL PASS, exit 0, no sanitizer report ---"
out="$("$BUILD_DIR/green" "$VECTORS" 2>&1)"; rc=$?
<<<"$out" grep -Eq "$SAN_RE" && { echo "  [green] GATE FAILURE: sanitizer report"; FAIL=1; }
if [ $rc -ne 0 ] || ! <<<"$out" grep -q "^ALL PASS$"; then
    echo "  [green] GATE FAILURE: shipped arm did not pass (rc=$rc)"; <<<"$out" grep "^FAIL:" | sed 's/^/      /'; FAIL=1
fi
for c in "${RED_CASES[@]}" "${GUARD_CASES[@]}"; do
    <<<"$out" grep -q "^RESULT $c pass$" && echo "  [green $c] passed" || { echo "  [green $c] GATE FAILURE: not passed"; FAIL=1; }
done
if words_match "$out" "$WANT_WORDS"; then echo "  [green words] the phrase has $WANT_WORDS words"
else echo "  [green words] GATE FAILURE: expected $WANT_WORDS words, the KAT counted: $(<<<"$out" grep '^WORDS' || echo none)"; FAIL=1; fi

done

echo "=== GUARD SELF-TEST (DERIV-24): the 24-word guard rejects a phrase that is not the one named"
ART="$CORE_DIR/vectors/derivation/abandon-art.txt"
sed '/^# mnemonic: /s/ art$/ about/' "$ART" > "$BUILD_DIR/bad-checksum.txt"
if cmp -s "$ART" "$BUILD_DIR/bad-checksum.txt"; then
    echo "  [self-test] GATE FAILURE: abandon-art.txt does not hold the phrase ending in \"art\""; FAIL=1
else
    out="$("$BUILD_DIR/green" "$BUILD_DIR/bad-checksum.txt" 2>&1)"; rc=$?
    <<<"$out" grep -Eq "$SAN_RE" && { echo "  [self-test] GATE FAILURE: sanitizer report"; FAIL=1; }
    if [ $rc -ne 0 ] && <<<"$out" grep -q "^RESULT mnemonic_bip39_valid fail$"; then
        echo "  [self-test] 24 words with a bad checksum: mnemonic_bip39_valid failed, as it must"
    else echo "  [self-test] GATE FAILURE: a bad-checksum phrase passed mnemonic_bip39_valid"; FAIL=1; fi
fi
out="$("$BUILD_DIR/green" "${VECTOR_FILES[0]}" 2>&1)"
if words_match "$out" 24 || ! words_match "$out" 12; then
    echo "  [self-test] GATE FAILURE: the word-count pairing does not tell 12 words from 24"; FAIL=1
else echo "  [self-test] a 12-word file held to 24 words is rejected"; fi

[ $FAIL -eq 0 ] && echo "derivation_vectors_kat: GATE HELD (the core derives and watches every independent vector, 12 and 24 words, with and without a passphrase)"
exit $FAIL
